cd /workspace && timeout 300 python3 - <<'EOF'
import sys, json, importlib.util
sys.path.insert(0,'/workspace/tmp')
import stress
spec = importlib.util.spec_from_file_location('m','/workspace/submission/main.py')
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
doc, cl = stress.build(K=32, nrib=2000, nq=512, qlen=64, nprior=2000, ndecl=2000, count=1000000)
try:
    m._parse(doc)
    print('parse ok')
except m.Invalid as e:
    print('parse invalid:', e)
try:
    m._process(doc)
    print('process ok')
except m.Invalid as e:
    print('process invalid:', e)
print('rib recs', len(doc['rib']), 'path len sum', sum(len(r['path']) for r in doc['rib']))
print('priors', len(doc['priors']), 'decl', len(doc['declared']), 'queries', len(doc['queries']))
norm_links=set()
for r in doc['rib']:
    p=[a for a in r['path'] if True]
    q=[]; 
    for a in p:
        if q and q[-1]==a: continue
        q.append(a)
    if len(q)>=2 and len(set(q))==len(q):
        for i in range(len(q)-1): norm_links.add(m._canon(q[i],q[i+1]))
print('distinct normalized links', len(norm_links))
EOF
